local p=Players[0]; local candidates={}; local boostable={}; for b in GameInfo.Boosts() do if b.TechnologyType then boostable[b.TechnologyType]=true end end;
for r in GameInfo.Technologies() do if boostable[r.TechnologyType] and not p:GetTechs():HasTech(r.Index) and not p:GetTechs():HasBoostBeenTriggered(r.Index) then candidates[#candidates+1]=r end end;
table.sort(candidates,function(a,b) return a.TechnologyType<b.TechnologyType end); if #candidates<2 then error('two new Eurekas required') end;
local tech,civic; for r in GameInfo.Technologies() do if r.Index~=candidates[1].Index and r.Index~=candidates[2].Index and p:GetTechs():CanResearch(r.Index) and p:GetTechs():GetResearchCost(r.Index)-p:GetTechs():GetResearchProgress(r.Index)>10 then tech=r; break end end;
for r in GameInfo.Civics() do if p:GetCulture():CanProgress(r.Index) and p:GetCulture():GetCultureCost(r.Index)-p:GetCulture():GetCulturalProgress(r.Index)>60 then civic=r; break end end;
if not tech or not civic then error('no research targets for exact yield checks') end;
UI.RequestPlayerOperation(0,PlayerOperations.RESEARCH,{[PlayerOperations.PARAM_TECH_TYPE]=tech.Hash,[PlayerOperations.PARAM_INSERT_MODE]=PlayerOperations.VALUE_EXCLUSIVE});
UI.RequestPlayerOperation(0,PlayerOperations.PROGRESS_CIVIC,{[PlayerOperations.PARAM_CIVIC_TYPE]=civic.Hash,[PlayerOperations.PARAM_INSERT_MODE]=PlayerOperations.VALUE_EXCLUSIVE});
ExposedMembers.JAC_RP_TestTargets={tech=tech.Index,civic=civic.Index}; return 'research selected'

local R=ExposedMembers.JAC_ReligionPersistence; local id='JAC_RP_PLACEHOLDER_03'; local p=Players[0]; local city=p:GetCities():GetCapitalCity():GetID(); 
local q=Players[1]; local c0=p:GetCities():GetCapitalCity(); local c1=q:GetCities():GetCapitalCity(); if not c1 then error('origin nation needs a city') end;
R.Found(id,1,'origin',1,0,'PLAYER_1'); R.SetCommunity(id,'origin',0,0,'PLAYER_1'); for _,outcome in ipairs({'SELL','CONCEAL','RESEARCH','HERESY','ABSORB','ARTIFACT','DIPLOMATIC_INCIDENT','HERO'}) do R.Discover(id,'choice_'..outcome,'material_'..outcome,'SCRIPTURE','ACTOR_'..outcome,'TRAVELER','CAVE',0) end;
-- Another community restores the native religion after the material discoveries.
q:GetReligion():SetHolyCity(c1); Game.GetReligion():FoundReligion(1,GameInfo.Religions.RELIGION_CUSTOM_2.Index);
if q:GetReligion():GetReligionTypeCreated()~=GameInfo.Religions.RELIGION_CUSTOM_2.Index then error('origin religion not founded') end;

R.SetCommunity('JAC_RP_PLACEHOLDER_02','adopter',1,0,'PLAYER_0');
R.BindEngineReligion(id,GameInfo.Religions.RELIGION_CUSTOM_2.Index); R.BindEngineReligion('JAC_RP_PLACEHOLDER_02',GameInfo.Religions.RELIGION_CUSTOM_1.Index);
c0:ChangePopulation(5-c0:GetPopulation()); c1:ChangePopulation(5-c1:GetPopulation());
c1:GetReligion():SetAllCityToReligion(GameInfo.Religions.RELIGION_CUSTOM_2.Index);
local cr=c0:GetReligion(); local src=GameInfo.Religions.RELIGION_CUSTOM_2.Index; local own=GameInfo.Religions.RELIGION_CUSTOM_1.Index;
cr:SetAllCityToReligion(-1); -- official Nubia scenario prepares unaffiliated citizens
local function weights(scale)
  for r in GameInfo.Religions() do if r.Index>0 then cr:RemovePressureOneReligion(r.Index,8388607,-1); cr:RemovePressureOneReligion(r.Index,1,-1) end end;
  cr:AddReligiousPressure(0,src,2*scale,-1); cr:AddReligiousPressure(0,own,scale,-1);
  local f,total={},0; for r in GameInfo.Religions() do if r.Index>0 then local n=cr:GetNumFollowers(r.Index); f[r.Index]=n; total=total+n end end;
  return f[src] or 0,f[own] or 0,5-total;
end;
local low,high,scale=0,nil,32; local ready=false;
for attempt=1,32 do local ns,nt,nu=weights(scale); if ns==2 and nt==1 and nu==2 then ready=true; break end; if nu>2 then low=scale else high=scale end; local nextScale=high and math.floor((low+high)/2) or scale*2; if nextScale<1 or nextScale==scale or nextScale==low then break end; scale=nextScale end;
if not ready then error('fixture needs two source, one own and two unaffiliated citizens') end;

if R.NativeFollowers(id)~=7 or R.Inspect(id).followers~=7 or R.Inspect(id).lost then error('native binding must reflect seven actual citizens') end; local ok=pcall(function() R.Discover(id,'illegal_live','illegal_material','SCRIPTURE','ACTOR','TRAVELER','CAVE',0) end); if ok then error('living native religion incorrectly accepted lost discovery') end;
p:GetReligion():ChangeFaithBalance(1000-p:GetReligion():GetFaithBalance()); q:GetTreasury():ChangeGoldBalance(501-q:GetTreasury():GetGoldBalance()); q:GetDiplomacy():ChangeFavor(101-q:GetDiplomacy():GetFavor());
return 'native citizens and balances prepared'

local R=ExposedMembers.JAC_ReligionPersistence; local id='JAC_RP_PLACEHOLDER_03'; local p=Players[0]; local city=p:GetCities():GetCapitalCity():GetID(); 
local s=R.Inspect(id); if s.followers~=4 or s.state~='UNDERGROUND' or not s.underground or s.canRevive then error('concealed continuity lost') end;
for _,o in ipairs({'SELL','CONCEAL','RESEARCH','HERESY','ABSORB','ARTIFACT','DIPLOMATIC_INCIDENT','HERO'}) do
local d=s.discoveries['choice_'..o]; if not d or d.outcome~=o or d.effects~='APPLIED' then error('missing applied choice '..o) end;
local before=R.Snapshot(); if pcall(R.ResolveDiscovery,id,'choice_'..o,o,{city=city,targetReligion='JAC_RP_PLACEHOLDER_02',targetPlayer=1}) then error('replay accepted '..o) end; if R.Snapshot()~=before then error('replay mutated ledger') end end;
if s.assets.material_RESEARCH~=nil or s.assets.material_HERESY~=nil or not s.retiredAssets.material_RESEARCH or not s.retiredAssets.material_HERESY then error('consumed material returned') end;
if s.assets.material_CONCEAL.holder~='HIDDEN_PLAYER_0' or not s.assets.material_ARTIFACT.vault then error('material disposition') end;
if s.assets.material_ABSORB~=nil or R.Inspect('JAC_RP_PLACEHOLDER_02').assets.material_ABSORB.originReligion~=id then error('absorption provenance lost') end;
if s.assets.material_DIPLOMATIC_INCIDENT.owner~=1 or R.CanPersecute(1,id,0,'JAC_RP_PLACEHOLDER_02') or R.CanPersecute(0,'JAC_RP_PLACEHOLDER_02',1,id) then error('returned material or alliance guards lost') end;
local h=R.Export().heroes['0']; local u=h and p:GetUnits():FindID(h.unit); if not u or h.verification~='APPLIED' then error('official hero lost') end;
if R.NativeFollowers(id)~=4 or R.NativeFollowers('JAC_RP_PLACEHOLDER_02')~=4 then error('native citizen conversion lost') end;
for _,t in ipairs(s.discoveries.choice_RESEARCH.effect.boosts) do if not p:GetTechs():HasBoostBeenTriggered(t) then error('saved Eureka missing') end end; return R.Snapshot()

