local R=ExposedMembers.JAC_ReligionPersistence; local id='JAC_RP_PLACEHOLDER_03'; local source=GameInfo.Religions.RELIGION_CUSTOM_2.Index;
for _,p in ipairs(PlayerManager.GetAlive()) do for _,c in p:GetCities():Members() do local cr=c:GetReligion(); cr:RemovePressureOneReligion(source,8388607,-1); cr:RemovePressureOneReligion(source,1,-1) end end;
if R.NativeFollowers(id)~=0 or not R.Inspect(id).lost then error('native loss must update ledger state') end;
